  guides.d2s01.signs=[['Man with Fish → Main Entrance','La escultura junto a la glorieta semicircular es tu referencia al llegar.'],['Abbott Oceanarium','Soundings Café queda en Ground Level y Bubble Net en Lower Level. Si buscas almorzar, sigue las señales de Lower Level.']];
  guides.d2s03.signs=[['East Entrance','Desde Shedd, busca la entrada a nivel del suelo. Si estás frente a Soldier Field, estás del lado de la entrada sur.'],['Griffin Halls of Evolving Planet','En el plano, busca ese nombre en el nivel superior: ahí está SUE.']];
  guides.d2s06.signs=[['Section 320','Cuando llegues al nivel 300, sigue este número, no las señales de suites o del club.'],['Guest Relations','Si te pasas de la sección, el recinto ubica atención al visitante frente a la 325.']];
  guides.d3s05.signs=[['Skydeck · Jackson Blvd','La señal útil es Skydeck en el lado sur de Willis Tower, no el letrero general de la torre.'],['The Ledge','Ya en el mirador, busca este nombre para los balcones de vidrio.']];
  guides.d4s05.signs=[['Wrigley Building → Chicago Water Taxi','Cruza al norte y busca el muelle al oeste del puente. Wendella comparte la zona; pregunta por Main Branch hacia Chinatown, no por un tour.'],['Ping Tom Park East','Al bajar, busca el pabellón de techo curvo junto al agua.']];
  guides.d5s02.signs=[['Harry Potter Shop · 676 N Michigan','Reconoce la tienda por el nombre y el número de la fachada, no por los escaparates de otras tiendas.'],['Butterbeer Bar','Dentro, busca ese nombre o pregunta dónde comienza la fila de bebidas.']];
  guides.d5s04.signs=[['West Gate','Desde la bajada #1143 mantente del lado del zoo y busca la puerta al este de Stockton.'],['Main Mall / South Lawn','Son los nombres que vas a encontrar en el plano oficial de ZooLights. Para volver, busca #1082 al otro lado de Stockton.']];
  guides.d3s07.signs=[['Navy Pier Terminal','Antes de entrar, fíjate dónde te dejó el bus; esta terminal es tu referencia para el regreso.'],['Billy Goat Tavern','Si vas a comer en el muelle, busca el nombre en el directorio antes de caminar hasta el extremo.']];
  guides['d4s08-fireworks'].signs=[['Exterior · vista al lago','Antes de las 8:00 p. m., busca un tramo abierto con vista despejada y respeta las zonas cerradas.'],['29 · 95th/Dan Ryan','Vuelve a la terminal #758 y comprueba el destino del bus, aunque sea el mismo punto donde bajaste.']];
  guides['d6-ord-pickup'].signs=[['Jackson · Blue Line','Busca Blue Line en Dearborn y O’Hare en el tablero del andén; Jackson Red Line es otra estación.'],['ATS / Terminal 5','Si te recogen en la Terminal 5, estas señales te llevan al tren interno sin entrar a seguridad.']];
  guides.d6s07.signs=[['Crystal Ridge · Ballpark Drive','Desde el estacionamiento dirígete al edificio de servicio antes de llevar el equipo a la nieve.'],['Ticketing / Rentals','Pide el pase, botas y casco y pregunta qué zona de principiantes está abierta esa noche. Acuerda volver a encontrarse junto al alquiler.']];
